// The place's vector geodata (locations/boni/geo) is generated by tools/ort/geodaten.py from the
// raw downloads checked in next to it. This test rebuilds it in memory and checks the result.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { execFileSync } from 'node:child_process';

const GEO = 'locations/boni/geo';
const read = (name) => JSON.parse(fs.readFileSync(`${GEO}/${name}`, 'utf8'));

test('geodata: a rebuild from the raw data matches the checked-in files and passes its checks', () => {
  const out = execFileSync('python3', ['tools/ort/geodaten.py', 'pruefen', 'tools/ort/boni.json'], { encoding: 'utf8' });
  assert.match(out, /bitgleich/);
  assert.doesNotMatch(out, /FEHLER/);
  assert.equal(read('pruefung.json').bestanden, true);
});

test('geodata: every layer lies in the official grid around the court', () => {
  const frame = read('rahmen.json');
  assert.equal(frame.crs, 'EPSG:25832');
  const [w, s, e, n] = frame.ausschnitt_utm32;
  const touches = (c) => (typeof c[0] === 'number' ? c[0] >= w && c[0] <= e && c[1] >= s && c[1] <= n : c.some(touches));
  for (const layer of ['gebaeude', 'nutzung', 'platz', 'wege', 'flaechen', 'baeume', 'einfriedungen', 'ausstattung', 'osm_gebaeude']) {
    const fc = read(`${layer}.geojson`);
    assert.ok(fc.features.length > 0, `${layer} is empty`);
    assert.ok(fc.lizenz && fc.quelle, `${layer} names no source or licence`);
    for (const f of fc.features) {
      const inside = touches(f.geometry.coordinates);
      const encloses = !inside && /Polygon/.test(f.geometry.type); // a big area may surround the window without a vertex in it
      assert.ok(inside || encloses, `${layer}: ${f.properties.oid ?? f.properties.osm} lies outside the area`);
      if (f.geometry.type === 'Polygon') for (const ring of f.geometry.coordinates) assert.deepEqual(ring[0], ring.at(-1), `${layer}: open ring`);
    }
  }
});

test('geodata: the court frame puts the fence corners where the game expects them', () => {
  const frame = read('rahmen.json'), court = read('platz.geojson');
  const [e0, n0] = frame.ursprung_utm32, a = frame.achse_a, b = frame.achse_b;
  assert.ok(Math.abs(a[0] * b[0] + a[1] * b[1]) < 1e-6, 'axes are not perpendicular');
  const corner = Object.fromEntries(court.features.filter((f) => f.properties.art === 'ecke').map((f) => {
    const [e, n] = f.geometry.coordinates;
    return [f.properties.name, [(e - e0) * a[0] + (n - n0) * a[1], (e - e0) * b[0] + (n - n0) * b[1]]];
  }));
  // A and B on the near end of axis a, D and C on the far end; A and D on the low side of axis b
  for (const [name, sa, sb] of [['A', -1, -1], ['B', -1, 1], ['C', 1, 1], ['D', 1, -1]]) {
    assert.ok(Math.abs(corner[name][0] - sa * 12.6) < 0.3, `${name}: a = ${corner[name][0]}`);
    assert.ok(Math.abs(corner[name][1] - sb * 9.0) < 0.3, `${name}: b = ${corner[name][1]}`);
  }
});
